//! WSJT-X 2.7.0-rc3's jt9 decoding signals that rr73-ft8 built (`fixtures/ft8/wsjtx_decodes.json`,
//! generated by `tools/wsjtx/decodes.sh` from `tools/wsjtx/decode_cases.txt`).
//!
//! jt9 must decode every message rr73-ft8 packs, in FT8 and FT4, to the text rr73-ft8 shows.
//! For the hand-built payloads, rr73-ft8 must show what jt9 shows, and reject what jt9 shows
//! nothing for, except for the forms in [`DIFFERENCES`].

mod common;

use common::payload;
use rr73_ft8::CallsignHashes;
use rr73_ft8::message::unpack;
use serde::Deserialize;

#[derive(Deserialize)]
struct File {
    generator: String,
    signals: Vec<Signal>,
}

#[derive(Deserialize)]
struct Signal {
    mode: String,
    source: String,
    note: String,
    payload: String,
    wsjtx_text: Option<String>,
}

/// Payloads jt9 shows that rr73-ft8 shows differently or rejects, by note, with the reason.
const DIFFERENCES: &[(&str, Option<&str>, &str)] = &[
    (
        "telemetry 0",
        Some("0"),
        "WSJT-X shows nothing; an empty decode cannot be read",
    ),
    (
        "K1ABC W9XYZ, g15 report code 187",
        None,
        "a report above +50 dB, which no encoder sends",
    ),
    (
        "K1ABC W9XYZ, g15 report code 367",
        None,
        "a report above +50 dB, which no encoder sends",
    ),
    (
        "K1ABC CQ -15 (word in the second field)",
        None,
        "CQ as the second callsign; no encoder sends it",
    ),
    (
        "type 0.6",
        None,
        "WSJT-X's WSPR-style type 0.6 is not implemented",
    ),
];

/// Replaces every `<...>` or `<CALL>` token with `<...>`: jt9 resolves hashes from other
/// decodes in the same slot, rr73-ft8 unpacks with an empty table here.
fn normalise(text: &str) -> String {
    text.split(' ')
        .map(|w| {
            if w.starts_with('<') && w.ends_with('>') {
                "<...>"
            } else {
                w
            }
        })
        .collect::<Vec<_>>()
        .join(" ")
}

#[test]
fn jt9_decodes_every_message_rr73_packs_in_both_modes() {
    let file: File = common::load("wsjtx_decodes.json");
    assert!(file.generator.contains("WSJT-X 2.7.0-rc3"), "{}", file.generator);
    let empty = CallsignHashes::new();
    let mut checked = [0usize; 2];
    for s in file.signals.iter().filter(|s| s.source.starts_with("text ")) {
        let ours = unpack(&payload(&s.payload), &empty).map(|m| m.to_string());
        let theirs = s
            .wsjtx_text
            .as_deref()
            .unwrap_or_else(|| panic!("jt9 did not decode {} in {}", s.source, s.mode));
        if s.note == "telemetry 0" {
            continue;
        }
        assert_eq!(
            ours.map(|t| normalise(&t)),
            Ok(normalise(theirs)),
            "{} in {}",
            s.source,
            s.mode
        );
        checked[usize::from(s.mode == "ft4")] += 1;
    }
    assert!(checked[0] >= 30 && checked[0] == checked[1], "{checked:?}");
}

#[test]
fn rr73_shows_what_jt9_shows() {
    let file: File = common::load("wsjtx_decodes.json");
    let empty = CallsignHashes::new();
    for s in &file.signals {
        let ours = unpack(&payload(&s.payload), &empty).map(|m| m.to_string());
        let what = format!("{} ({}, {})", s.note, s.source, s.mode);
        if let Some((_, expected, reason)) = DIFFERENCES.iter().find(|(note, _, _)| *note == s.note) {
            assert!(
                s.wsjtx_text.is_some(),
                "{what}: jt9 shows nothing; listed as a difference"
            );
            match expected {
                Some(text) => assert_eq!(ours.as_deref(), Ok(*text), "{what}: {reason}"),
                None => assert!(ours.is_err(), "{what}: {reason}; shown as {ours:?}"),
            }
            continue;
        }
        match s.wsjtx_text.as_deref() {
            // jt9 prints nothing, or an empty message, for payloads WSJT-X cannot unpack.
            None | Some("") => assert!(
                ours.is_err(),
                "{what}: jt9 shows nothing, rr73-ft8 shows {ours:?}"
            ),
            Some(text) => assert_eq!(ours.map(|t| normalise(&t)), Ok(normalise(text)), "{what}"),
        }
    }
}
